<?php
namespace App\Http\Resources; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\JsonResource;
class OrderResource extends JsonResource { public static $wrap=null; public function toArray(Request $request): array{return ['id'=>$this->id,'order_number'=>$this->order_number,'submission_token'=>$this->submission_token,'shift_id'=>$this->shift_id,'cashier_id'=>$this->cashier_id,'customer_name'=>$this->customer_name,'order_type'=>$this->order_type->value,'table_number'=>$this->table_number,'status'=>$this->status->value,'subtotal'=>$this->subtotal,'discount_total'=>$this->discount_total,'tax_total'=>$this->tax_total,'grand_total'=>$this->grand_total,'notes'=>$this->notes,'paid_at'=>$this->paid_at?->toISOString(),'items'=>$this->whenLoaded('items',fn()=>$this->items->map(fn($i)=>['id'=>$i->id,'product_id'=>$i->product_id,'name'=>$i->product_name_snapshot,'variant'=>$i->variant_name_snapshot,'unit_price'=>$i->unit_price,'quantity'=>$i->quantity,'line_total'=>$i->line_total,'notes'=>$i->notes,'modifiers'=>$i->modifiers->map(fn($m)=>['id'=>$m->id,'name'=>$m->name_snapshot,'price_adjustment'=>$m->price_adjustment])])),'payment'=>$this->whenLoaded('payment',fn()=>new PaymentResource($this->payment))];} }
